from collections import defaultdict


class Feed:
    def __init__(self, k: int):
        self.k = k
        self.time = 0
        self.posts = defaultdict(list)       # user -> [(time, post_id)]
        self.following = defaultdict(set)

    def post(self, user: int, post_id: int) -> None:
        self.time += 1
        self.posts[user].append((self.time, post_id))

    def follow(self, follower: int, followee: int) -> None:
        self.following[follower].add(followee)

    def unfollow(self, follower: int, followee: int) -> None:
        self.following[follower].discard(followee)

    def latest(self, user: int) -> list[int]:
        mine = [p for a in self.following[user] | {user} for p in self.posts[a]]
        mine.sort(reverse=True)              # every post of every author, every time
        return [post_id for _, post_id in mine[:self.k]]


def run_feed(k: int, ops: list[list]) -> list:
    feed = Feed(k)
    return [getattr(feed, name)(*args) for name, *args in ops]
